// The sheet's bracket ledger shows the total momentum of its people in each bracket, Q4 down to Q1 (zero
// when none are); people whose bracket is "n/a" add nothing.
  protected readonly bracketLedger = computed(() =>
    BRACKETS.map((bracket) => ({
      bracket,
      total: this.people()
        .filter((p) => this.bracketOf(p) === bracket)
        .reduce((total, p) => total + (p.momentum ?? 0), 0),
    })),
  );

